'use strict';
/*
 * Eight recent exact-model references, stored only on the visitor's device.
 * Premium source-derived thumbnails and a direct path to the existing factual
 * comparison. Never fetch third-party images or infer prices/availability.
 */
(() => {
  const key='atelier-montres-unified-recent-v1';
  const valid=id=>typeof id==='string'&&/^[a-z0-9-]{4,64}$/.test(id);
  const read=()=>{
    try{
      const raw=JSON.parse(localStorage.getItem(key)||'[]');
      return Array.isArray(raw)?[...new Set(raw.filter(valid))].slice(0,8):[];
    }catch{return null;}
  };
  const article=document.querySelector('main article.watch-product[data-watch-id],main article.am-extra-product[data-popular-watch-id]');
  if(article){
    const id=article.dataset.watchId||article.dataset.popularWatchId;
    const brand=article.dataset.brand,model=article.dataset.model;
    if(!valid(id)||!brand||!model||article.querySelector('h1')?.textContent?.trim()!==brand+' '+model
      ||location.pathname!=='/montres/'+id+'.html')return;
    const ids=read();
    if(ids===null)return;
    try{localStorage.setItem(key,JSON.stringify([id,...ids.filter(x=>x!==id)].slice(0,8)));}catch{}
    return;
  }
  const grid=document.querySelector('#udGrid');
  const section=document.querySelector('[data-unified-recent]');
  const list=section?.querySelector('[data-unified-recent-list]');
  const clear=section?.querySelector('[data-unified-recent-clear]');
  if(!grid||!section||!list||!clear)return;
  const cards=new Map([...grid.querySelectorAll('article.ud-card[data-id]')]
    .filter(card=>valid(card.dataset.id)&&card.dataset.brand&&card.dataset.model
      &&card.querySelector('h2')?.textContent?.trim()===card.dataset.brand+' '+card.dataset.model)
    .map(card=>[card.dataset.id,card]));
  if(cards.size!==52)return;

  const text=(tag,value,cls)=>{
    const element=document.createElement(tag);
    if(value!==null)element.textContent=value;
    if(cls)element.className=cls;
    return element;
  };
  // Permit only the exact source image from this model and local, generated
  // responsive derivatives. Never copy arbitrary image URLs out of the DOM.
  const localAsset=(raw,id)=>{
    try{
      const url=new URL(raw,location.href);
      if(url.origin!==location.origin||url.hash||url.username||url.password)return false;
      // The build appends a SHA-256 cache key to approved responsive WebPs.
      // Keep only that exact syntax; arbitrary URLs and query strings remain blocked.
      if(url.search&&!/^\?v=[a-f0-9]{12}$/.test(url.search))return false;
      return url.pathname==='/assets/watches/'+id+'.webp'
        ||url.pathname==='/assets/watches-popular/'+id+'.webp'
        ||new RegExp('^/assets/(?:watch-responsive|popular-responsive)/'+id+'-[0-9]+\\.webp$').test(url.pathname);
    }catch{return false;}
  };
  const photoFor=(card,id)=>{
    if(card.dataset.visual!=='photo')return null;
    const source=card.querySelector('.ud-photo img');
    if(!source||!localAsset(source.getAttribute('src'),id))return null;
    const img=document.createElement('img');
    img.src=source.getAttribute('src');
    const originalSet=source.getAttribute('srcset')||'';
    if(originalSet){
      const candidates=originalSet.split(',').map(piece=>piece.trim().split(/\s+/));
      if(candidates.every(parts=>parts.length===2&&/^[1-9][0-9]*w$/.test(parts[1])
        &&localAsset(parts[0],id)))img.srcset=originalSet;
    }
    img.sizes='(max-width: 700px) 140px, 220px';
    img.width=220;
    img.height=160;
    img.loading='lazy';
    img.decoding='async';
    img.alt=''; // Adjacent exact-model text labels the whole linked card.
    return img;
  };

  const actions=text('div',null,'am-unified-recent-compare');
  actions.hidden=true;
  const message=text('p','', 'am-unified-recent-compare-status');
  message.setAttribute('role','status');
  message.setAttribute('aria-live','polite');
  const compareLink=text('a','Comparer les montres','am-unified-recent-compare-link');
  compareLink.hidden=true;
  const reset=text('button','Réinitialiser la sélection','am-unified-recent-reset');
  reset.type='button';
  actions.append(message,compareLink,reset);
  list.after(actions);
  let chosen=[];

  const updateCompare=()=>{
    chosen=chosen.filter(id=>cards.has(id)&&list.querySelector('[data-recent-watch-id="'+id+'"]'));
    for(const button of list.querySelectorAll('button[data-recent-compare-id]')){
      const id=button.dataset.recentCompareId;
      const selected=chosen.includes(id);
      button.setAttribute('aria-pressed',String(selected));
      button.textContent=selected?'Retirer de la comparaison':'Sélectionner pour comparer';
      const card=cards.get(id);
      button.setAttribute('aria-label',button.textContent+' '
        +(card?.dataset.brand||'')+' '+(card?.dataset.model||''));
    }
    actions.hidden=chosen.length===0;
    message.textContent=chosen.length===1?'Une montre choisie. Sélectionnez-en une deuxième.'
      :chosen.length+' montres sélectionnées sur 3 maximum.';
    compareLink.hidden=chosen.length<2;
    if(chosen.length>=2){
      compareLink.href='?compare='+chosen.join(',')+'#comparer';
      compareLink.textContent='Comparer '+chosen.length+' montres';
    }else compareLink.removeAttribute('href');
  };

  const render=()=>{
    const ids=read();
    list.replaceChildren();
    if(!ids){chosen=[];actions.hidden=true;section.hidden=true;return;}
    for(const id of ids){
      const card=cards.get(id);
      if(!card)continue;
      const item=text('article',null,'am-unified-recent-item');
      item.dataset.recentWatchId=id;
      const link=text('a',null,'am-unified-recent-link');
      link.href='./'+id+'.html';
      const media=text('span',null,'am-unified-recent-media');
      const photo=photoFor(card,id);
      if(photo){
        media.append(photo);
        media.append(text('span','Photo du modèle','am-unified-recent-visual-label'));
      }else{
        media.classList.add('am-unified-recent-media-fallback');
        const fallback=text('span',null,'am-unified-recent-fallback');
        fallback.append(text('small','PHOTO NON PUBLIÉE'),
          text('strong',card.dataset.brand),text('span','Voir la fiche de la marque'));
        media.append(fallback);
      }
      const details=text('span',null,'am-unified-recent-info');
      const range=card.querySelector('.ud-tier-pill')?.textContent?.trim()||'Sélection documentée';
      details.append(text('small',range,'am-unified-recent-range'),
        text('strong',card.dataset.brand+' '+card.dataset.model,'am-unified-recent-name'),
        text('span','Voir la fiche et les sources','am-unified-recent-see'));
      link.append(media,details);
      const pick=text('button','Sélectionner pour comparer','am-unified-recent-pick');
      pick.type='button';
      pick.dataset.recentCompareId=id;
      pick.setAttribute('aria-pressed','false');
      item.append(link,pick);
      list.append(item);
    }
    section.hidden=!list.childElementCount;
    updateCompare();
  };
  list.addEventListener('click',event=>{
    const button=event.target.closest('button[data-recent-compare-id]');
    if(!button||!list.contains(button))return;
    const id=button.dataset.recentCompareId;
    if(!cards.has(id)||!list.querySelector('[data-recent-watch-id="'+id+'"]'))return;
    if(chosen.includes(id))chosen=chosen.filter(value=>value!==id);
    else if(chosen.length<3)chosen.push(id);
    else{
      actions.hidden=false;
      message.textContent='Trois montres maximum. Retirez-en une avant d’en ajouter une autre.';
      return;
    }
    updateCompare();
  });
  reset.addEventListener('click',()=>{chosen=[];updateCompare();});
  clear.addEventListener('click',()=>{
    try{localStorage.removeItem(key);}catch{return;}
    chosen=[];
    render();
  });
  window.addEventListener('pageshow',render);
  window.addEventListener('storage',event=>{if(event.key===key)render();});
  render();
})();

/* Source-backed merchant entrypoints for the 52-watch public catalogue.
   Editorial counts only: no implied offer prices, stock, commission or sales. */
.ud-page .ud-paths{margin:36px 0 30px;padding:clamp(19px,3vw,33px);border:1px solid #d2dccc;border-radius:9px;background:linear-gradient(135deg,#f9faf4,#f1f3ea);color:#254434}
.ud-paths-header{display:flex;justify-content:space-between;align-items:end;gap:16px 36px;margin-bottom:19px}
.ud-paths-header>div{min-width:0;max-width:60%}
.ud-paths-header>div>span{display:block;margin-bottom:7px;color:#7e6142;text-transform:uppercase;letter-spacing:.11em;font:800 10px/1.5 system-ui,sans-serif}
.ud-paths-header h2{margin:0;font:400 clamp(26px,3.1vw,39px)/1.2 Georgia,serif;letter-spacing:-.03em;color:#1e3f2d;text-wrap:balance}
.ud-paths-header>p{max-width:43ch;margin:0;color:#485d4d;font:450 13px/1.7 system-ui,sans-serif}
.ud-path-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px}
.ud-path-link{--path-accent:#597d61;position:relative;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:215px;padding:18px;border:1px solid #cdd9cb;border-radius:6px;background:#fffefa;color:#254534;text-decoration:none;box-shadow:0 6px 20px rgba(31,57,35,.05);transition:border-color .18s ease,box-shadow .18s ease}
.ud-path-link[data-merchant-path="direct"]{--path-accent:#29734a;border-top:4px solid #29734a}
.ud-path-link[data-merchant-path="awin"]{--path-accent:#536d99;border-top:4px solid #536d99}
.ud-path-link[data-merchant-path="search"]{--path-accent:#967041;border-top:4px solid #967041}
.ud-path-link[data-merchant-path="official"]{--path-accent:#5e7770;border-top:4px solid #5e7770}
.ud-path-icon{position:absolute;top:14px;right:15px;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#eef2ea;color:var(--path-accent);font:750 20px/1 system-ui,sans-serif}
.ud-path-eyebrow{padding-right:27px;color:#546c56;letter-spacing:.04em;text-transform:uppercase;font:750 10px/1.45 system-ui,sans-serif}
.ud-path-link strong{display:block;max-width:22ch;font:400 clamp(21px,2.2vw,27px)/1.19 Georgia,serif;color:#21422f;letter-spacing:-.018em}
.ud-path-description{color:#516558;font:450 12px/1.6 system-ui,sans-serif}
.ud-path-count{display:inline-flex;justify-content:space-between;align-items:center;gap:9px;margin-top:auto;padding:10px 0 0;border-top:1px solid #dce2d8;color:#24503a;font:800 12px/1.5 system-ui,sans-serif}
.ud-path-link:hover{border-color:var(--path-accent);box-shadow:0 12px 30px rgba(24,55,31,.13)}
.ud-path-link:focus-visible{outline:3px solid #b68a44;outline-offset:3px}
.ud-paths-disclosure{max-width:103ch;margin:15px 0 0;color:#4f6153;font:450 12px/1.75 system-ui,sans-serif}
@media(max-width:850px){
 .ud-paths-header{display:block}
 .ud-paths-header>div{max-width:none}
 .ud-paths-header>p{margin-top:11px;max-width:70ch}
}
@media(max-width:650px){
 .ud-page .ud-paths{margin:27px 0 25px;padding:18px 15px}
 .ud-path-links{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x proximity;overscroll-behavior-x:contain;scrollbar-width:thin;scrollbar-color:#9aac9b #edf0e8;padding:3px 3px 14px;margin:0 -3px}
 .ud-path-link{flex:0 0 min(84%,310px);min-height:220px;scroll-snap-align:start}
}
@media(prefers-reduced-motion:reduce){.ud-path-link{transition:none}}

/* Atelier Montres · visual finishing for the public 52-watch collection.
 * Editorial ranges are NOT verified price brackets. No additional images,
 * fonts, scripts, merchant endpoints or remote resources. */
.ud-tier-navigation{margin:clamp(36px,5vw,66px) 0 35px;padding:0;min-width:0;color:#203e2d}
.ud-tier-navigation-head{display:flex;justify-content:space-between;align-items:end;gap:18px 35px;margin:0 0 22px}
.ud-tier-navigation-eyebrow{display:block;margin:0 0 10px;color:#866742;letter-spacing:.11em;text-transform:uppercase;font:800 11px/1.5 system-ui,sans-serif}
.ud-tier-navigation h2{margin:0;font:400 clamp(30px,4vw,48px)/1.13 Georgia,serif;letter-spacing:-.035em;color:#193b2a;text-wrap:balance}
.ud-tier-navigation-head>p{max-width:44ch;margin:0;color:#4a6250;font:400 14px/1.75 system-ui,sans-serif}
.ud-tier-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.ud-tier-shortcut{--tone:#8a8f70;min-width:0;display:flex;flex-direction:column;gap:10px;min-height:226px;padding:24px 23px 19px;position:relative;overflow:hidden;border:1px solid #d4d8c9;border-top:4px solid var(--tone);border-radius:7px;background:#fffcf5;color:#20412e;text-decoration:none;box-shadow:0 9px 27px rgba(24,51,31,.055);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.ud-tier-shortcut::after{content:"";position:absolute;right:-50px;top:-44px;width:155px;aspect-ratio:1;border:20px solid color-mix(in srgb,var(--tone),transparent 83%);border-radius:50%;pointer-events:none}
.ud-tier-shortcut[data-tier-shortcut="essential"]{--tone:#749779;background:linear-gradient(135deg,#f7faf4,#fffdf7)}
.ud-tier-shortcut[data-tier-shortcut="signature"]{--tone:#ab8754;background:linear-gradient(135deg,#fbf5e8,#fffdfa)}
.ud-tier-shortcut[data-tier-shortcut="prestige"]{--tone:#61788c;background:linear-gradient(135deg,#eff3f7,#fffdf8)}
.ud-tier-shortcut-index{position:relative;z-index:1;color:#4c6552;letter-spacing:.14em;font:750 10px/1.5 system-ui,sans-serif}
.ud-tier-shortcut strong{position:relative;z-index:1;font:400 clamp(23px,2.6vw,31px)/1.16 Georgia,serif;letter-spacing:-.025em}
.ud-tier-shortcut-desc{position:relative;z-index:1;color:#4b5e4e;font:450 13px/1.65 system-ui,sans-serif;max-width:35ch}
.ud-tier-shortcut-footer{position:relative;z-index:1;margin-top:auto;padding-top:12px;border-top:1px solid #cdd7ca;color:#23513a;font:750 12px/1.4 system-ui,sans-serif;display:flex;justify-content:space-between;gap:10px}
.ud-tier-shortcut-footer span{font-size:19px;line-height:1}
.ud-tier-shortcut:hover{border-color:var(--tone);box-shadow:0 16px 33px rgba(27,52,34,.12);transform:translateY(-3px)}
.ud-tier-shortcut:focus-visible{outline:3px solid #b88b44;outline-offset:4px}
.ud-tier-disclaimer{margin:13px 0 0;color:#5a6959;font:450 12px/1.7 system-ui,sans-serif}
/* Watch cards retain the existing source, comparison and commercial flows.
   A discrete collection signature helps shoppers compare at a glance. */
.ud-page .ud-grid{align-items:stretch}
.ud-page .ud-card{--card-accent:#829983;position:relative;border:1px solid #d4ddcf;border-radius:9px;box-shadow:0 10px 25px rgba(29,57,36,.067);transition:border-color .17s ease,box-shadow .17s ease;isolation:isolate}
.ud-page .ud-card[data-tier="essential"]{--card-accent:#618a70}
.ud-page .ud-card[data-tier="signature"]{--card-accent:#a67e43}
.ud-page .ud-card[data-tier="prestige"]{--card-accent:#55758c}
.ud-page .ud-card::before{content:"";height:4px;position:absolute;z-index:4;top:0;left:0;right:0;background:var(--card-accent);pointer-events:none}
.ud-page .ud-card:hover{border-color:#9bb5a0;box-shadow:0 17px 36px rgba(28,54,36,.13)}
.ud-page .ud-card-main{gap:11px}
.ud-page .ud-card .ud-kicker{display:flex;align-items:center;flex-wrap:wrap;gap:7px 9px;letter-spacing:normal;text-transform:none}
.ud-page .ud-tier-pill{display:inline-flex;align-items:center;min-height:27px;padding:5px 9px;border-radius:4px;border:1px solid color-mix(in srgb,var(--card-accent),white 55%);background:color-mix(in srgb,var(--card-accent),white 90%);color:#284633;font:800 10px/1.4 system-ui,sans-serif;letter-spacing:.018em}
.ud-page .ud-card[data-tier="signature"] .ud-tier-pill{color:#725328}
.ud-page .ud-card[data-tier="prestige"] .ud-tier-pill{color:#2c526c}
.ud-page .ud-card-style{font:600 11px/1.5 system-ui,sans-serif;color:#607062}
.ud-page .ud-card h2{letter-spacing:-.02em;text-wrap:pretty}
.ud-page .ud-description{color:#405c49}
.ud-page .ud-card-main>dl{padding:11px 12px;background:#f5f6f0;border:1px solid #e4e7dd;border-radius:5px;gap:11px}
.ud-page .ud-card-main>dl>div{padding-top:0;border:0}
.ud-page .ud-offer-context{border-radius:5px;overflow-wrap:anywhere}
.ud-page .ud-merchant-kind{max-width:100%;font-size:11px;line-height:1.45}
.ud-page .ud-card .ud-actions a{min-height:48px;border-radius:5px;line-height:1.5;padding:11px 12px;text-wrap:pretty;overflow-wrap:anywhere}
.ud-page .ud-card .ud-actions .ud-details{background:#244d35;color:#fff!important;border:1px solid #244d35}
.ud-page .ud-card .ud-actions .ud-details:hover{background:#345f45}
.ud-page .ud-card[data-merchant="direct"] .ud-actions .ud-merchant,
.ud-page .ud-card[data-merchant="awin"] .ud-actions .ud-merchant{background:#e8f0e5;border:1px solid #7ba183;color:#1e5033!important;font-weight:800}
.ud-page .ud-card[data-merchant="direct"] .ud-actions .ud-merchant:hover,
.ud-page .ud-card[data-merchant="awin"] .ud-actions .ud-merchant:hover{background:#dceadb}
.ud-page .ud-card[data-merchant="search"] .ud-actions .ud-merchant{background:#f9f2e6;border-color:#ccb58b;color:#654920!important}
.ud-page .ud-card[data-merchant="search"] .ud-actions .ud-source{border-color:#7d9d82}
.ud-page .ud-card .ud-actions :is(a,button):focus-visible,
.ud-page .ud-card .ud-select:focus-visible{outline:3px solid #b88b44;outline-offset:3px}
@media(max-width:900px){
 .ud-tier-navigation-head{display:block}
 .ud-tier-navigation-head>p{margin:12px 0 0}
 .ud-tier-shortcut{padding:20px 17px;min-height:224px}
}
@media(max-width:650px){
 .ud-tier-navigation{margin:35px 0 28px}
 .ud-tier-shortcuts{display:flex;overflow-x:auto;gap:12px;scroll-snap-type:x proximity;overscroll-behavior-x:contain;padding:4px 4px 14px;margin:0 -4px;scrollbar-width:thin;scrollbar-color:#97a995 #edece5}
 .ud-tier-shortcut{flex:0 0 min(83%,325px);scroll-snap-align:start;min-height:205px}
 .ud-page .ud-card-main>dl{padding:9px}
}
@media(max-width:420px){
 .ud-page .ud-grid.ud-view-large .ud-card-main>dl{padding:11px}
 .ud-page .ud-grid:not(.ud-view-large) .ud-card-main>dl{padding:8px}
}
@media(prefers-reduced-motion:reduce){
 .ud-tier-shortcut,.ud-page .ud-card{transition:none}
 .ud-tier-shortcut:hover{transform:none}
}

/* Source-derived commercial confidence on all 52 editorial watch cards.
   The marker describes link quality only; never a verified offer or stock. */
.ud-page .ud-card-main>.ud-trust-marker{
  display:inline-flex;align-items:center;align-self:flex-start;gap:8px;
  max-width:100%;min-height:27px;box-sizing:border-box;
  margin:0;padding:5px 10px;border:1px solid #cad6cb;border-radius:4px;
  background:#eef4ed;color:#274a36;
  font:750 10px/1.4 system-ui,sans-serif;letter-spacing:.015em;
  overflow-wrap:anywhere
}
.ud-page .ud-trust-dot{
  display:inline-block;flex:none;width:7px;height:7px;
  border-radius:50%;background:#386a49
}
.ud-page .ud-card-main>.ud-trust-marker[data-merchant-confidence="awin"]{
  background:#edf2f4;border-color:#c6d5da;color:#305467
}
.ud-page .ud-trust-marker[data-merchant-confidence="awin"] .ud-trust-dot{background:#49738a}
.ud-page .ud-card-main>.ud-trust-marker[data-merchant-confidence="search"]{
  background:#faf4e9;border-color:#decda9;color:#6c522d
}
.ud-page .ud-trust-marker[data-merchant-confidence="search"] .ud-trust-dot{background:#a27a3d}
.ud-page .ud-card-main>.ud-trust-marker[data-merchant-confidence="official"]{
  background:#f1f1ef;border-color:#d5d9d3;color:#4e6055
}
.ud-page .ud-trust-marker[data-merchant-confidence="official"] .ud-trust-dot{background:#7b897f}
@media(max-width:650px){
  .ud-page .ud-card-main>.ud-trust-marker{
    min-height:26px;padding:5px 8px;font-size:10px;line-height:1.35
  }
}

'use strict';
/* Handcrafted vector drawings, not official product photography. No third-party image rights needed. */
(() => {
  const NS='http://www.w3.org/2000/svg';
  const colors={turquoise:['#ade8dc','#4d8d94'],blue:['#bdd5e8','#285474'],green:['#7eba9c','#185a41'],black:['#6c8075','#142522'],ivory:['#fbf5e5','#beb49b'],silver:['#e5e9e2','#879b91'],transparent:['#d8f1ea','#88b9b3']};
  const types={
   'casio-a168wa':'digital','casio-mtp-b145':'square','casio-mtp-1302':'date',
   'casio-mdv107':'diver','casio-ltp1302':'date-small','swatch-clearly':'transparent',
   'citizen-eco':'eco','citizen-openheart':'openheart','citizen-tsuyosa':'integrated',
   'orient-bambino':'leather','seiko-5':'diver','tissot-prx-quartz':'integrated',
   'tissot-prx-auto':'textured','hamilton-khaki':'field','seiko-sharp':'textured'
  };
  function el(tag,attrs,txt){
   const e=document.createElementNS(NS,tag);
   for(const [k,v] of Object.entries(attrs||{})) if(v!==null&&v!==undefined)e.setAttribute(k,String(v));
   if(txt!==undefined)e.textContent=String(txt);
   return e;
  }
  function put(parent,tag,attrs,txt){const child=el(tag,attrs,txt);parent.appendChild(child);return child;}
  function render(mount,p,compact){
   if(!mount||!p)return;
   const id=String(p.id||'dial').replace(/[^a-z0-9-]/gi,'').slice(0,64);
   const type=types[id]||'date';
   const tone=colors[p.tone]||colors.green;
   const svg=el('svg',{xmlns:NS,viewBox:'0 0 340 380',role:'img',focusable:'false','aria-label':'Interprétation vectorielle du style '+p.brand+' '+p.model+', différente de la photo réelle',class:'am-watch-svg'});
   const defs=put(svg,'defs');
   let g=put(defs,'linearGradient',{id:'steel-'+id,x1:'0%',y1:'0%',x2:'100%',y2:'30%'});
